-- Q1. What is the total revenue generated by male and female customers?
USE customer_behaviour;

SELECT
    gender,
    SUM(purchase_amount) AS revenue
FROM customer_data
GROUP BY gender;


-- Q2. Which customers used a discount and spent more than the average purchase amount?
SELECT
    customer_id,
    purchase_amount
FROM customer_data
WHERE discount_applied = 'Yes'
AND purchase_amount > (
    SELECT AVG(purchase_amount)
    FROM customer_data
);


-- Q3. What are the top 5 products with the highest average review ratings?
SELECT
    item_purchased,
    AVG(review_rating) AS average_product_rating
FROM customer_data
GROUP BY item_purchased
ORDER BY average_product_rating DESC
LIMIT 5;


-- Q4. What is the average purchase amount for Standard and Express shipping?
SELECT
    shipping_type,
    AVG(purchase_amount) AS average_purchase_amount
FROM customer_data
WHERE shipping_type IN ('Standard', 'Express')
GROUP BY shipping_type;


-- Q5. Compare the average spending and total revenue of subscribed and non-subscribed customers.
SELECT
    subscription_status,
    AVG(purchase_amount) AS average_spend,
    SUM(purchase_amount) AS total_revenue
FROM customer_data
GROUP BY subscription_status;


-- Q6. Which top 5 products have the highest percentage of purchases with discounts applied?
SELECT
    item_purchased,
    COUNT(
        CASE WHEN discount_applied = 'Yes'
        THEN 1 END
    ) * 100.0 / COUNT(*) AS discount_percentage
FROM customer_data
GROUP BY item_purchased
ORDER BY discount_percentage DESC
LIMIT 5;


-- Q7. Segment customers into New, Returning, and Loyal based on their previous purchases.
SELECT
    customer_segment,
    COUNT(*) AS total_customers
FROM (
    SELECT
        customer_id,
        CASE
            WHEN previous_purchases = 1 THEN 'New'
            WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
            ELSE 'Loyal'
        END AS customer_segment
    FROM customer_data
) AS segments
GROUP BY customer_segment;


-- Q8. What are the top 3 most purchased products in each category?
WITH product_counts AS (
    SELECT
        category,
        item_purchased,
        COUNT(*) AS total_purchases
    FROM customer_data
    GROUP BY category, item_purchased
),
ranked_products AS (
    SELECT
        category,
        item_purchased,
        total_purchases,
        DENSE_RANK() OVER (
            PARTITION BY category
            ORDER BY total_purchases DESC
        ) AS product_rank
    FROM product_counts
)
SELECT
    category,
    item_purchased,
    total_purchases
FROM ranked_products
WHERE product_rank <= 3
ORDER BY category, total_purchases DESC;


-- Q9. Are repeat buyers (more than 5 previous purchases) more likely to subscribe?
SELECT
    CASE
        WHEN previous_purchases > 5
        THEN 'Repeat Buyers'
        ELSE 'Other Customers'
    END AS customer_type,
    COUNT(*) AS total_customers,
    SUM(subscription_status = 'Yes') AS subscribed_customers,
    ROUND(
        100.0 * SUM(subscription_status = 'Yes') / COUNT(*),
        2
    ) AS subscription_percentage
FROM customer_data
GROUP BY customer_type;


-- Q10. What is the revenue contribution of each age group?
SELECT
    age_group,
    SUM(purchase_amount) AS total_revenue
FROM customer_data
GROUP BY age_group
ORDER BY total_revenue DESC;